import { useEffect, useRef, useState, useCallback } from 'react'
import { Star, Quote } from 'lucide-react'

const GAP = 20

const testimonials = [
  {
    name: 'James Mwangi',
    role: 'Hospitality Director',
    company: 'Tribe Hotel, Nairobi',
    image: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR_wufnbZqmr8QYd5Q5UjFgDkmizutxojyTWg&s',
    review: 'Wavonex transformed our entire HVAC infrastructure. From design to commissioning, their team was professional, on-schedule, and genuinely understood our hospitality requirements. Our guests now enjoy consistent comfort year-round.',
    stars: 5,
  },
  {
    name: 'Sarah Odhiambo',
    role: 'Operations Manager',
    company: 'Naivas Supermarkets',
    image: 'data:image/jpeg;base64,',
    review: 'We engaged Wavonex to install cold room systems across three branches. Their cold chain expertise is exceptional👍from temperature monitoring to compliance documentation, everything was handled flawlessly. Zero product loss since installation.',
    stars: 5,
  },
  {
    name: 'Dr. Aisha Hassan',
    role: 'Facility Director',
    company: 'Aga Khan University Hospital',
    image: 'data:image/jpeg;base64,',
    review: 'In a healthcare environment, HVAC reliability is non-negotiable. Wavonex delivered a fully redundant system with BMS integration. Their 24/7 emergency response has saved us twice already.',
    stars: 5,
  },
  {
    name: 'Peter Kamau',
    role: 'CEO',
    company: 'Kamau Cold Chain Logistics',
    image: 'data:image/jpeg;base64,',
    review: 'Our entire refrigeration fleet was designed and installed by Wavonex. They understood temperature-sensitive logistics perfectly. Competitive pricing, quality equipment, and after-sales support that is truly outstanding.',
    stars: 5,
  },
  {
    name: 'Grace Biyaki',
    role: 'Property Manager',
    company: 'Westlands Commercial Park',
    image: 'data:image/jpeg;base64,',
    review: 'Managing a multi-tenant commercial building means HVAC issues affect dozens of businesses. Wavonex installed a central VRF system and has maintained it for two years without a single major breakdown.',
    stars: 5,
  },
  {
    name: 'David Otieno',
    role: 'Managing Director',
    company: 'Otieno Food Industries',
    image: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSOKGVMAyr-4gguZxEtI-p-Uajojm0Ce020tQ&s',
    review: 'Food safety depends on precise refrigeration. Wavonex built our blast freezer and cold storage rooms to exact specifications. Inspections have been smooth ever since — full compliance, every time.',
    stars: 5,
  },
  {
    name: 'Amina Yusuf',
    role: 'CEO',
    company: 'Savanna Solar Solutions',
    image: 'https://images.unsplash.com/photo-1598550874175-4d0ef436c909?w=150&h=150&fit=crop&crop=face&q=80',
    review: 'We partnered with Wavonex on a large commercial solar installation. Their hybrid system design cut our client\'s electricity bill by 60%. Technical knowledge, timely delivery👌— it\'s everything we needed.',
    stars: 5,
  },
  {
    name: 'Margaret Mburu',
    role: 'Facilities Manager',
    company: 'Two Rivers Mall',
    image: 'https://peopledaily.digital/wp-content/uploads/2022/03/Phyllis-Wakiaga.jpg',
    review: 'Maintaining comfortable temperatures across a shopping mall this size is a massive challenge. Wavonex handles our entire PPM contract and responds to emergencies faster than any contractor we have used before.',
    stars: 5,
  },
  {
    name: 'Linda Chebet',
    role: 'Director of Operations',
    company: 'Highlands Dairy Ltd',
    image: 'data:image/jpeg;base64,',
    review: 'Dairy processing demands uninterrupted refrigeration. Wavonex designed a redundant chiller system that has run without failure for 18 months. Their team genuinely understands industrial cooling at scale.',
    stars: 5,
  },
]

export default function Testimonials() {
  const [current, setCurrent] = useState(0)
  const [paused, setPaused] = useState(false)
  const [visibleCount, setVisibleCount] = useState(3)
  const [translateX, setTranslateX] = useState(0)
  const containerRef = useRef(null)
  const headerRef = useRef(null)
  const intervalRef = useRef(null)
  const [visible, setVisible] = useState(false)

  const maxIndex = testimonials.length - visibleCount

  const calcTranslate = useCallback((index, vc) => {
    if (!containerRef.current) return 0
    const w = containerRef.current.offsetWidth
    const cardW = (w - (vc - 1) * GAP) / vc
    return index * (cardW + GAP)
  }, [])

  useEffect(() => {
    setTranslateX(calcTranslate(current, visibleCount))
  }, [current, visibleCount, calcTranslate])

  useEffect(() => {
    const update = () => {
      const w = window.innerWidth
      const vc = w <= 600 ? 1 : w <= 900 ? 2 : 3
      setVisibleCount(vc)
      setCurrent(c => Math.min(c, testimonials.length - vc))
    }
    update()
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])

  const next = useCallback(() => {
    setCurrent(c => (c >= testimonials.length - visibleCount ? 0 : c + 1))
  }, [visibleCount])

  useEffect(() => {
    if (paused) { clearInterval(intervalRef.current); return }
    intervalRef.current = setInterval(next, 4000)
    return () => clearInterval(intervalRef.current)
  }, [paused, next])

  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) { setVisible(true); obs.disconnect() }
    }, { threshold: 0.1 })
    if (headerRef.current) obs.observe(headerRef.current)
    return () => obs.disconnect()
  }, [])

  const cardWidth = `calc((100% - ${(visibleCount - 1) * GAP}px) / ${visibleCount})`

  return (
    <section style={{ background: '#fff', padding: 'clamp(56px,7vw,100px) 20px' }}>
      <div style={{ maxWidth: 1200, margin: '0 auto' }}>

        {/* Header */}
        <div
          ref={headerRef}
          style={{
            textAlign: 'center',
            marginBottom: 48,
            opacity: visible ? 1 : 0,
            transform: visible ? 'translateY(0)' : 'translateY(24px)',
            transition: 'opacity 0.6s ease, transform 0.6s ease',
          }}
        >
          <div style={{ display: 'inline-block', background: '#0D1B3E', color: '#F5C518', fontSize: 11, letterSpacing: 3, textTransform: 'uppercase', fontWeight: 700, padding: '4px 16px', borderRadius: 20, marginBottom: 16 }}>
            Client Reviews
          </div>
          <h2 style={{ fontFamily: 'Barlow Condensed', fontWeight: 900, fontSize: 'clamp(28px,5vw,50px)', color: '#0D1B3E', textTransform: 'uppercase', lineHeight: 1.05, marginBottom: 12 }}>
            Trusted by Businesses<br />Across East Africa
          </h2>
          <p style={{ color: '#666', fontSize: 15, maxWidth: 460, margin: '0 auto', lineHeight: 1.6 }}>
            Real results from real clients — see why leading companies choose Wavonex.
          </p>
        </div>

        {/* Slider — no side padding needed since arrows are removed */}
        <div
          ref={containerRef}
          style={{ overflow: 'hidden' }}
          onMouseEnter={() => setPaused(true)}
          onMouseLeave={() => setPaused(false)}
        >
          <div
            style={{
              display: 'flex',
              gap: GAP,
              transform: `translateX(-${translateX}px)`,
              transition: 'transform 0.55s cubic-bezier(0.4,0,0.2,1)',
            }}
          >
            {testimonials.map((t, i) => (
              <div
                key={i}
                style={{
                  flex: `0 0 ${cardWidth}`,
                  width: cardWidth,
                  background: '#F4F4F4',
                  borderRadius: 14,
                  padding: 'clamp(18px,2.5vw,28px)',
                  boxShadow: '0 3px 20px rgba(0,0,0,0.07)',
                  position: 'relative',
                  boxSizing: 'border-box',
                  display: 'flex',
                  flexDirection: 'column',
                  minHeight: 260,
                }}
              >
                <div style={{ position: 'absolute', top: 14, right: 14, color: '#F5C518', opacity: 0.18 }}>
                  <Quote size={44} strokeWidth={1} />
                </div>

                <div style={{ display: 'flex', gap: 3, marginBottom: 12 }}>
                  {[...Array(t.stars)].map((_, si) => (
                    <Star key={si} size={14} fill="#F5C518" color="#F5C518" />
                  ))}
                </div>

                <p style={{
                  fontSize: 'clamp(12px,1.3vw,14px)',
                  color: '#444',
                  lineHeight: 1.75,
                  fontStyle: 'italic',
                  flex: 1,
                  marginBottom: 20,
                  fontFamily: 'DM Sans, sans-serif',
                }}>
                  "{t.review}"
                </p>

                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                  <img
                    src={t.image}
                    alt={t.name}
                    style={{ width: 44, height: 44, borderRadius: '50%', objectFit: 'cover', border: '3px solid #F5C518', flexShrink: 0 }}
                  />
                  <div>
                    <div style={{ fontFamily: 'Barlow Condensed', fontWeight: 700, fontSize: 'clamp(14px,1.6vw,17px)', color: '#0D1B3E' }}>
                      {t.name}
                    </div>
                    <div style={{ fontSize: 11, color: '#999', marginTop: 2 }}>
                      {t.role} &middot; {t.company}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Dot indicators */}
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: 8, marginTop: 28 }}>
          {Array.from({ length: maxIndex + 1 }).map((_, i) => (
            <button
              key={i}
              onClick={() => setCurrent(i)}
              aria-label={`Go to slide ${i + 1}`}
              style={{
                width: i === current ? 28 : 10, height: 10, borderRadius: 5,
                background: i === current ? '#F5C518' : '#d0d0d0',
                border: 'none', cursor: 'pointer',
                transition: 'width 0.35s ease, background 0.35s ease',
                padding: 0,
              }}
            />
          ))}
        </div>


      </div>
    </section>
  )
}
